1	// Package logfile persists event batches as an append-only sequence of
2	// length-prefixed, CRC-checked frames.
3	//
4	// Frame layout (all integers big-endian):
5	//
6	//	[4 bytes payload length][4 bytes CRC32-IEEE of payload][payload bytes]
7	//
8	// The payload is a JSON array encoded with events.MarshalBatch.
9	package logfile
10	
11	import (
12		"encoding/binary"
13		"errors"
14		"fmt"
15		"hash/crc32"
16		"os"
17		"path/filepath"
18		"sync"
19	
20		"github.com/cocosolocoder/signalroom/internal/events"
21	)
22	
23	const (
24		logName  = "events.log"
25		lockName = "lock"
26	
27		headerSize = 8
28		// maxPayload guards against absurd allocations when a corrupt length
29		// prefix happens to point inside the file.
30		maxPayload = 64 << 20
31	)
32	
33	// ErrPoisoned is returned after a write or sync failure. The log refuses all
34	// further writes until the process is restarted and recovery succeeds.
35	var ErrPoisoned = errors.New("event log is unavailable after a storage failure")
36	
37	// Log is an append-only, concurrency-safe frame writer holding an exclusive
38	// directory lock for its lifetime.
39	type Log struct {
40		mu       sync.Mutex
41		file     *os.File
42		lockFile *os.File
43		dir      string
44		key      []byte
45		poisoned bool
46	}
47	
48	// CorruptionError marks a complete frame that fails its checksum or contains
49	// illegal data, as opposed to an incomplete trailing frame.
50	type CorruptionError struct{ Reason string }
51	
52	func (e *CorruptionError) Error() string { return e.Reason }
53	
54	func corruption(format string, args ...any) error {
55		return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
56	}
57	
58	// Open acquires an exclusive lock on the data directory, creates it if
59	// needed, replays the log, and truncates at most one incomplete trailing
60	// frame (a torn final write). A corrupt frame in the middle, or a complete
61	// frame containing illegal data, is fatal: Open returns an error without
62	// modifying the file.
63	//
64	// Recovered batches are returned in write order, ready to load into a
65	// timeline.
66	func Open(dir string) (*Log, [][]events.Event, error) {
67		if dir == "" {
68			return nil, nil, errors.New("data directory is required")
69		}
70		if err := os.MkdirAll(dir, 0o755); err != nil {
71			return nil, nil, fmt.Errorf("create data directory: %w", err)
72		}
73	
74		lockPath := filepath.Join(dir, lockName)
75		lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
76		if err != nil {
77			return nil, nil, fmt.Errorf("open directory lock: %w", err)
78		}
79		if err := tryLock(lockFile); err != nil {
80			lockFile.Close()
81			if errors.Is(err, errLocked) {
82				return nil, nil, fmt.Errorf("data directory %q is in use by another signalroom instance", dir)
83			}
84			return nil, nil, fmt.Errorf("acquire directory lock: %w", err)
85		}
86	
87		path := filepath.Join(dir, logName)
88		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
89		if err != nil {
90			unlock(lockFile)
91			lockFile.Close()
92			return nil, nil, fmt.Errorf("open event log: %w", err)
93		}
94	
95		batches, validLen, err := replay(file)
96		if err != nil {
97			file.Close()
98			unlock(lockFile)
99			lockFile.Close()
100			return nil, nil, err
101		}
102		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
103			// Drop exactly one incomplete trailing frame. This is the only
104			// mutation recovery performs, so it is fsynced before serving.
105			if err := file.Truncate(validLen); err != nil {
106				file.Close()
107				unlock(lockFile)
108				lockFile.Close()
109				return nil, nil, fmt.Errorf("truncate incomplete trailing frame: %w", err)
110			}
111			if err := file.Sync(); err != nil {
112				file.Close()
113				unlock(lockFile)
114				lockFile.Close()
115				return nil, nil, fmt.Errorf("sync event log: %w", err)
116			}
117		}
118		if err := syncDir(dir); err != nil {
119			file.Close()
120			unlock(lockFile)
121			lockFile.Close()
122			return nil, nil, fmt.Errorf("sync data directory: %w", err)
123		}
124	
125		key, err := loadOrCreateKey(dir)
126		if err != nil {
127			file.Close()
128			unlock(lockFile)
129			lockFile.Close()
130			return nil, nil, err
131		}
132	
133		return &Log{file: file, lockFile: lockFile, dir: dir, key: key}, batches, nil
134	}
135	
136	// replay scans the log and returns the valid batches, the byte offset at
137	// which the log is known good, and an error for any corruption before that
138	// offset.
139	func replay(file *os.File) ([][]events.Event, int64, error) {
140		data, err := os.ReadFile(file.Name())
141		if err != nil {
142			return nil, 0, fmt.Errorf("read event log: %w", err)
143		}
144	
145		var batches [][]events.Event
146		pos := int64(0)
147		for pos < int64(len(data)) {
148			remaining := int64(len(data)) - pos
149			if remaining < headerSize {
150				// Torn partial header: ignore everything from here on.
151				break
152			}
153			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
154			if payloadLen <= 0 || payloadLen > maxPayload {
155				return nil, 0, corruption("corrupt frame header at offset %d", pos)
156			}
157			frameEnd := pos + headerSize + payloadLen
158			if frameEnd > int64(len(data)) {
159				// Header landed but its payload did not: torn trailing frame.
160				break
161			}
162			payload := data[pos+headerSize : frameEnd]
163			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
164			if crc32.ChecksumIEEE(payload) != wantCRC {
165				return nil, 0, corruption("checksum mismatch at offset %d", pos)
166			}
167			batch, err := events.DecodeBatch(payload)
168			if err != nil {
169				return nil, 0, corruption("illegal frame payload at offset %d: %v", pos, err)
170			}
171			if len(batch) == 0 {
172				return nil, 0, corruption("empty batch frame at offset %d", pos)
173			}
174			for i := range batch {
175				normalized, err := events.Normalize(batch[i])
176				if err != nil {
177					return nil, 0, corruption("invalid event in frame at offset %d: %v", pos, err)
178				}
179				batch[i] = normalized
180			}
181			batches = append(batches, batch)
182			pos = frameEnd
183		}
184		return batches, pos, nil
185	}
186	
187	// Append durably writes one batch. The bytes hit the disk (write followed by
188	// fsync) before Append returns. Any write or sync failure poisons the log:
189	// this call and every later one return ErrPoisoned until restart.
190	func (l *Log) Append(batch []events.Event) (err error) {
191		payload, err := events.MarshalBatch(batch)
192		if err != nil {
193			return fmt.Errorf("encode batch: %w", err)
194		}
195		if len(payload) > maxPayload {
196			return fmt.Errorf("batch exceeds %d byte frame limit", maxPayload)
197		}
198	
199		frame := make([]byte, headerSize+len(payload))
200		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
201		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
202		copy(frame[headerSize:], payload)
203	
204		l.mu.Lock()
205		defer l.mu.Unlock()
206		if l.poisoned {
207			return ErrPoisoned
208		}
209		defer func() {
210			if err != nil {
211				l.poisoned = true
212			}
213		}()
214	
215		if _, err = l.file.Write(frame); err != nil {
216			return fmt.Errorf("write event log: %w", err)
217		}
218		if err = l.file.Sync(); err != nil {
219			return fmt.Errorf("sync event log: %w", err)
220		}
221		return nil
222	}
223	
224	// Poisoned reports whether the log has suffered an unrecoverable write error.
225	func (l *Log) Poisoned() bool {
226		l.mu.Lock()
227		defer l.mu.Unlock()
228		return l.poisoned
229	}
230	
231	// Close releases the log and the exclusive directory lock.
232	func (l *Log) Close() error {
233		l.mu.Lock()
234		defer l.mu.Unlock()
235		var closeErr error
236		if err := l.file.Close(); err != nil {
237			closeErr = err
238		}
239		if err := unlock(l.lockFile); err != nil && closeErr == nil {
240			closeErr = err
241		}
242		if err := l.lockFile.Close(); err != nil && closeErr == nil {
243			closeErr = err
244		}
245		return closeErr
246	}
