54			// recovery performs, fsynced before serving.
55			if err := file.Truncate(validLen); err != nil {
56				file.Close()
57				return nil, nil, fmt.Errorf("truncate incomplete trailing incident frame: %w", err)
58			}
59			if err := file.Sync(); err != nil {
60				file.Close()
61				return nil, nil, fmt.Errorf("sync incident log: %w", err)
62			}
