124		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
125		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
126		copy(frame[headerSize:], payload)
127	
128		l.mu.Lock()
129		defer l.mu.Unlock()
130		if l.poisoned {
131			return ErrPoisoned
132		}
133		defer func() {
134			if err != nil {
135				l.poisoned = true
136			}
137		}()
138	
