22	func TestAppendAndReopen(t *testing.T) {
23		dir := t.TempDir()
24		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
25	
26		log, batches, err := Open(dir)
27		if err != nil {
28			t.Fatalf("open: %v", err)
29		}
30		if err := log.Append([]events.Event{testEvent("a", base), testEvent("b", base.Add(time.Second))}); err != nil {
31			t.Fatalf("append: %v", err)
32		}
33		if err := log.Append([]events.Event{testEvent("c", base.Add(2*time.Second))}); err != nil {
34			t.Fatalf("append: %v", err)
35		}
36		if err := log.Close(); err != nil {
37			t.Fatalf("close: %v", err)
38		}
39	
40		log2, batches, err := Open(dir)
41		if err != nil {
42			t.Fatalf("reopen: %v", err)
43		}
44		defer log2.Close()
45		if len(batches) != 2 || len(batches[0]) != 2 || len(batches[1]) != 1 {
46			t.Fatalf("unexpected recovered batches: %+v", batches)
47		}
48		flat := []string{batches[0][0].ID, batches[0][1].ID, batches[1][0].ID}
49		if strings.Join(flat, ",") != "a,b,c" {
50			t.Fatalf("recovery order: %v", flat)
51		}
52		if !batches[0][0].At.Equal(base) {
53			t.Fatalf("timestamp not preserved absolutely: %v", batches[0][0].At)
54		}
55	
56		// A new batch after recovery appends cleanly and reads back as frame 3.
57		if err := log2.Append([]events.Event{testEvent("d", base.Add(3*time.Second))}); err != nil {
58			t.Fatalf("append after recovery: %v", err)
59		}
60		if err := log2.Close(); err != nil {
61			t.Fatalf("close: %v", err)
62		}
63		_, batches, err = Open(dir)
64		if err != nil {
65			t.Fatalf("reopen 2: %v", err)
66		}
67		if len(batches) != 3 || batches[2][0].ID != "d" {
68			t.Fatalf("post-tail-write corrupted recovery: %+v", batches)
69		}
70	}
