72	func TestReplayIgnoresTornTailOnly(t *testing.T) {
73		dir := t.TempDir()
74		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
75		path := filepath.Join(dir, logName)
76	
77		log, _, err := Open(dir)
78		if err != nil {
79			t.Fatalf("open: %v", err)
80		}
81		if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
82			t.Fatalf("append: %v", err)
83		}
84		if err := log.Append([]events.Event{testEvent("b", base.Add(time.Second))}); err != nil {
85			t.Fatalf("append: %v", err)
86		}
87		log.Close()
88	
89		good, err := os.ReadFile(path)
90		if err != nil {
91			t.Fatalf("read: %v", err)
92		}
93	
94		// Torn payload: full header promising more bytes than exist.
95		payload, _ := events.MarshalBatch([]events.Event{testEvent("torn", base.Add(2*time.Second))})
96		partialHeader := make([]byte, 5) // also exercises a short partial header
97		binary.BigEndian.PutUint32(partialHeader[0:4], uint32(len(payload)))
98	
99		cases := map[string][]byte{
100			"partial header":  partialHeader,
101			"partial payload": frameFor(payload)[:headerSize+3],
102			"full header only": func() []byte {
103				b := make([]byte, headerSize)
104				binary.BigEndian.PutUint32(b[0:4], uint32(len(payload)))
105				binary.BigEndian.PutUint32(b[4:8], crc32.ChecksumIEEE(payload))
106				return b
107			}(),
108		}
109		for name, tail := range cases {
110			t.Run(name, func(t *testing.T) {
111				if err := os.WriteFile(path, append(append([]byte(nil), good...), tail...), 0o644); err != nil {
112					t.Fatalf("seed torn file: %v", err)
113				}
114				log2, batches, err := Open(dir)
115				if err != nil {
116					t.Fatalf("torn tail must be tolerated: %v", err)
117				}
118				if len(batches) != 2 {
119					t.Fatalf("want 2 intact batches, got %d", len(batches))
120				}
121				// Ignored tail must not pollute the next write.
122				if err := log2.Append([]events.Event{testEvent("after", base.Add(3*time.Second))}); err != nil {
123					t.Fatalf("append over torn tail: %v", err)
124				}
