140	// frameFor wraps a payload the same way Log.Append does.
141	func frameFor(payload []byte) []byte {
142		frame := make([]byte, headerSize+len(payload))
143		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
144		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
145		copy(frame[headerSize:], payload)
146		return frame
147	}
